def solve(inG):
    H,W=len(inG),len(inG[0])
    from collections import Counter
    cnt=Counter(v for row in inG for v in row)
    fill=cnt.most_common(1)[0][0]
    line_rows=[r for r in range(H) if fill not in inG[r]]
    line_cols=[c for c in range(W) if all(inG[r][c]!=fill for r in range(H))]
    line=Counter(inG[r][c] for r in line_rows for c in line_cols).most_common(1)[0][0]
    marks={}
    for r in line_rows:
        for c in line_cols:
            if inG[r][c]!=line: marks[(r,c)]=inG[r][c]
    canvas=[[marks.get((r,c),fill) for c in line_cols] for r in line_rows]
    mrs=sorted({i for i,r in enumerate(line_rows) for c in line_cols if (r,c) in marks})
    mcs=sorted({j for j,c in enumerate(line_cols) for r in line_rows if (r,c) in marks})
    crop=[row[min(mcs):max(mcs)+1] for row in canvas[min(mrs):max(mrs)+1]]
    out=[]
    for a in range(len(crop)-1):
        row=[]
        for b in range(len(crop[0])-1):
            blk={crop[a+i][b+j] for i in (0,1) for j in (0,1)}
            row.append(next(iter(blk)) if len(blk)==1 else fill)
        out.append(row)
    return out
